// Sanitize the incoming webhook payload. Handle missing and invalid values
// so downstream AI agents always receive a complete, well-typed record.
const b = ($json.body && typeof $json.body === 'object') ? $json.body : $json;

const missing = [];
const invalid = [];

function num(key, def, min, max) {
  const raw = b[key];
  if (raw === undefined || raw === null || raw === '') { missing.push(key); return def; }
  const n = Number(raw);
  if (!Number.isFinite(n)) { invalid.push(key); return def; }
  if (min !== undefined && n < min) { invalid.push(key); return def; }
  if (max !== undefined && n > max) { invalid.push(key); return def; }
  return n;
}
function str(key, def) {
  const raw = b[key];
  if (typeof raw !== 'string' || raw.trim() === '') { if (raw === undefined || raw === null || raw === '') missing.push(key); return def; }
  return raw.trim();
}
function bool(key, def) {
  const raw = b[key];
  if (typeof raw === 'boolean') return raw;
  if (raw === 'true') return true;
  if (raw === 'false') return false;
  if (raw === undefined || raw === null || raw === '') { missing.push(key); return def; }
  invalid.push(key);
  return def;
}

const normalized = {
  residentId: str('residentId', 'UNKNOWN'),
  name: str('name', 'Unknown Resident'),
  age: num('age', 0, 0, 130),
  gender: str('gender', 'Unknown'),
  heartRate: num('heartRate', 0, 0, 300),
  spo2: num('spo2', 0, 0, 100),
  bloodPressure: str('bloodPressure', 'N/A'),
  temperature: num('temperature', 0, 25, 45),
  respiratoryRate: num('respiratoryRate', 0, 0, 80),
  sleepHours: num('sleepHours', 0, 0, 24),
  steps: num('steps', 0, 0, 100000),
  stressLevel: num('stressLevel', 0, 0, 100),
  cameraEvent: str('cameraEvent', 'none'),
  fallDetected: bool('fallDetected', false),
  medicationTaken: bool('medicationTaken', true),
  timestamp: str('timestamp', $now.toISO()),
};

normalized.dataQuality = {
  missingFields: missing,
  invalidFields: invalid,
  complete: missing.length === 0 && invalid.length === 0,
};

return normalized;

