// Merge all agent outputs into the single JSON contract the React app consumes.
const input = $('Normalize & Validate Input').item.json || {};
const health = ($('Health Monitoring Agent').item.json.output) || {};
const risk = ($('Risk Prediction Agent').item.json.output) || {};
const emerg = ($('Emergency Agent').item.json.output) || {};
const rec = ($('Recommendation Agent').item.json.output) || {};
const report = ($('Caregiver Report Agent').item.json.output) || {};

// Derive an overall risk level from the individual risk signals.
const fallRisk = Number(risk.fallRisk) || 0;
const levels = [risk.heartRisk, risk.sleepRisk, risk.activityRisk].map(v => String(v || '').toLowerCase());
const highCount = levels.filter(v => v === 'high').length;
const medCount = levels.filter(v => v === 'medium').length;
const isEmergency = emerg.emergency === true;

let riskLevel = 'Low';
if (isEmergency || fallRisk >= 70 || highCount >= 1) riskLevel = 'High';
else if (fallRisk >= 40 || medCount >= 1) riskLevel = 'Medium';

const recommendations = Array.isArray(rec.recommendations) ? rec.recommendations : [];

return {
  // ---- Primary contract returned to the frontend ----
  residentId: input.residentId,
  name: input.name,
  healthScore: Number(health.healthScore) || 0,
  overallHealth: health.overallHealth || 'Unknown',
  riskLevel: riskLevel,
  emergency: isEmergency,
  fallRisk: fallRisk,
  heartRisk: risk.heartRisk || 'Low',
  sleepRisk: risk.sleepRisk || 'Low',
  activityRisk: risk.activityRisk || 'Low',
  summary: health.summary || '',
  recommendations: recommendations,
  caregiverReport: report.caregiverReport || '',
  // ---- Extended detail (also persisted to Firestore) ----
  nextCheckup: report.nextCheckup || '',
  emergencyDetails: isEmergency ? {
    priority: emerg.priority || '',
    reason: emerg.reason || '',
    immediateAction: emerg.immediateAction || '',
    hospitalRecommendation: emerg.hospitalRecommendation || '',
    emergencyContactRecommendation: emerg.emergencyContactRecommendation || '',
  } : null,
  dataQuality: input.dataQuality || {},
  timestamp: input.timestamp,
  processedAt: $now.toISO(),
};
